// Valida cada salida contra las reglas de los prompts (ver docs/validacion_prompts_v2.md).
// Es un primer filtro automatico: la fidelidad al contenido hay que revisarla leyendo la columna "salida".
const wc = s => String(s || '').trim().split(/\s+/).filter(Boolean).length;

const EXPECT = {
  linkedin: {
    '1': { omitido: false, tipo: 'logro_laboral', prohibido: /contratad|seleccionad|contrataron|fichad/i },
    '2': { omitido: false, tipo: 'logro_laboral' },
    '3': { omitido: false, tipo: 'experiencia_proyecto' },
    '4': { omitido: false, tipo: 'aprendizaje_tecnico' },
    '5': { omitido: true }
  },
  newsletter: {
    'N1': { status: 'generado', prohibido: /contratad|seleccionad|contrataron/i },
    'N2': { status: 'generado' },
    'N3': { status: 'generado', sinSeccion: 'Logro de la Semana' },
    'N4': { status: 'insuficiente' },
    'N5': { status: 'generado', sinIds: true }
  },
  faq: {
    '1': { formatos: ['TIP', 'NINGUNO'] },
    '2': { omitido: true },
    '3': { formatos: ['FAQ', 'NINGUNO'] },
    '4': { formatos: ['FAQ', 'NINGUNO'] },
    '5': { formatos: ['FAQ', 'NINGUNO'] }
  }
};

function checkLinkedIn(o, src, exp, P, A) {
  if (exp.omitido === true) {
    if (o.omitido !== true) P.push('Se esperaba omitido:true (no hay testimonios).');
    return;
  }
  if (o.omitido === true) { P.push('Marco omitido:true pero habia material: ' + (o.motivo || '')); return; }
  for (const k of ['titulo', 'copy', 'canal_recomendado', 'potencial_engagement', 'hashtags', 'origen_interacciones'])
    if (!(k in o)) P.push('Falta el campo ' + k);
  if (typeof o.copy === 'string') {
    const n = wc(o.copy);
    if (n < 80 || n > 150) P.push(`copy tiene ${n} palabras (rango 80-150)`);
    if (o.copy.includes('#')) P.push('copy contiene hashtags (deben ir solo en el campo hashtags)');
    if (exp.prohibido && exp.prohibido.test(o.copy)) P.push('copy habla de contratacion/seleccion que no esta en los datos');
  }
  if (!['Alto', 'Medio', 'Bajo'].includes(o.potencial_engagement)) P.push('potencial_engagement fuera de Alto/Medio/Bajo');
  if (Array.isArray(o.hashtags)) {
    if (o.hashtags.length < 3 || o.hashtags.length > 4) A.push(`hashtags: ${o.hashtags.length} (se piden 3-4)`);
    if (o.hashtags.some(h => !String(h).startsWith('#'))) P.push('hay hashtags sin #');
  } else if ('hashtags' in o) P.push('hashtags no es una lista');
  if (typeof o.titulo === 'string' && o.titulo.length > 90) A.push('titulo con mas de 90 caracteres');
  if (Array.isArray(o.origen_interacciones)) {
    const bad = o.origen_interacciones.filter(a => !src.autores.includes(a));
    if (bad.length) P.push('origen_interacciones con autores que no estan en el lote: ' + bad.join(', '));
  }
  if (exp.tipo && o.tipo_experiencia !== exp.tipo) A.push(`tipo_experiencia = ${o.tipo_experiencia} (esperado ${exp.tipo})`);
  const textoLi = String(o.titulo || '') + ' ' + String(o.copy || '');
  if (/\b(dominio|domina|domino|dominó|experto|experta)\b/i.test(textoLi)) A.push('habla de dominio o experticia: verificar que la persona lo haya dicho');
  if (/^c[oó]mo\b/i.test(String(o.titulo || '').trim())) A.push('el titulo empieza con "Como": ¿promete un tutorial que el post no es?');
}

function checkNewsletter(o, src, exp, P, A) {
  for (const k of ['status', 'titulo', 'introduccion', 'secciones', 'cierre', 'motivo'])
    if (!(k in o)) P.push('Falta el campo ' + k);
  if (!['generado', 'insuficiente'].includes(o.status)) P.push('status fuera de generado/insuficiente');
  if (exp.status && o.status !== exp.status) P.push(`status = ${o.status} (esperado ${exp.status})`);
  if (!Array.isArray(o.secciones)) { P.push('secciones no es una lista'); return; }
  if (o.status === 'insuficiente') {
    if (o.secciones.length) P.push('status insuficiente pero trae secciones');
    if (!o.motivo) P.push('status insuficiente sin motivo');
    return;
  }
  const orden = ['Logro de la Semana', 'Tema en Tendencia', 'Dato de la Comunidad'];
  let ultimo = -1;
  const textos = [o.introduccion, o.cierre];
  for (const s of o.secciones) {
    const i = orden.indexOf(s.titulo);
    if (i < 0) P.push('Titulo de seccion no permitido: ' + s.titulo);
    else { if (i < ultimo) P.push('Secciones fuera de orden'); ultimo = i; }
    if (typeof s.contenido !== 'string') { P.push('contenido no es texto en ' + s.titulo); continue; }
    textos.push(s.contenido);
    if (s.contenido.trim().startsWith(s.titulo)) A.push('contenido repite el titulo en ' + s.titulo);
    if (/(^|\n)\s*([#>*-]|\d+\.)\s/.test(s.contenido)) A.push('posible Markdown en ' + s.titulo);
    if (!Array.isArray(s.ids_actividades)) P.push('ids_actividades no es lista en ' + s.titulo);
    else {
      const bad = s.ids_actividades.filter(id => !src.ids.includes(String(id)));
      if (bad.length) P.push(`ids inventados en ${s.titulo}: ${bad.join(', ')}`);
      if (exp.sinIds && s.ids_actividades.length) P.push('el lote no trae ids y aun asi devolvio ids_actividades');
      if (src.idsNumericos && s.ids_actividades.some(id => typeof id !== 'number')) P.push('ids_actividades debe contener numeros (no texto) en ' + s.titulo);
    }
  }
  if (exp.sinSeccion && o.secciones.some(s => s.titulo === exp.sinSeccion)) P.push(`No deberia incluir "${exp.sinSeccion}" (no hay datos)`);
  const todo = textos.join(' ');
  const n = wc(todo);
  if (n > 250) P.push(`texto total de ${n} palabras (maximo 250)`);
  if (n < 60) A.push(`texto total de ${n} palabras (minimo sugerido 60)`);
  if (exp.prohibido && exp.prohibido.test(todo)) P.push('habla de contratacion/seleccion que no esta en los datos');
  const dato = o.secciones.find(s => s.titulo === 'Dato de la Comunidad');
  if (dato && src.total !== null && !String(dato.contenido).includes(String(src.total))) A.push(`Dato de la Comunidad no menciona el total (${src.total})`);
  if (/\b(muchos|muchas|varios|varias|la mayoria|la mayoría|cada vez más|cada vez mas)\b/i.test(todo)) A.push('usa cuantificadores vagos (muchos/varios/la mayoria): verificar que los datos lo respalden');
  if (typeof o.titulo === 'string' && wc(o.titulo) > 12) A.push('titulo con mas de 12 palabras');
  if (/\b(inconveniente|contratiempo)\b/i.test(todo)) A.push('posible suavizado del feedback ("inconveniente"): comparar con las palabras originales');
}

function checkFaq(o, src, exp, P, A) {
  for (const k of ['tema', 'origen', 'status', 'contenido_sugerido', 'formato'])
    if (!(k in o)) P.push('Falta el campo ' + k);
  if (exp.omitido) {
    if (o.status !== 'omitido' || o.omitido !== true) P.push('Se esperaba status "omitido" y omitido:true (no hay dudas)');
    return;
  }
  if (!['borrador_para_curaduria', 'derivado_a_mentoria'].includes(o.status)) P.push('status inesperado: ' + o.status);
  if (!['FAQ', 'TIP', 'NINGUNO'].includes(o.formato)) P.push('formato fuera de FAQ/TIP/NINGUNO');
  if (exp.formatos && !exp.formatos.includes(o.formato)) A.push(`formato = ${o.formato} (esperado ${exp.formatos.join(' o ')})`);
  const pref = { FAQ: 'FAQ: ', TIP: 'Tip rápido: ', NINGUNO: 'Consulta para mentoría: ' }[o.formato];
  if (pref && !String(o.tema).startsWith(pref)) P.push(`tema deberia empezar con "${pref}"`);
  if (o.formato === 'NINGUNO' && o.status !== 'derivado_a_mentoria') P.push('formato NINGUNO requiere status derivado_a_mentoria');
  if ((o.formato === 'FAQ' || o.formato === 'TIP') && o.status !== 'borrador_para_curaduria') P.push('FAQ/TIP requiere status borrador_para_curaduria');
  const c = String(o.contenido_sugerido || '');
  const n = wc(c);
  if (n < 50 || n > 140) P.push(`contenido_sugerido tiene ${n} palabras (rango 50-140)`);
  for (const a of src.autores) if (a && c.includes(a)) P.push('contenido_sugerido incluye el nombre de ' + a);
  if (/`|https?:\/\//i.test(c)) P.push('contiene codigo o enlaces');
  if (/\b(pip install|npm (install|i|run)|docker (run|pull|compose|exec|build)|kubectl \w+|git (clone|commit|push|pull))\b/i.test(c)) A.push('parece incluir comandos: revisar');
  if (!String(o.origen).startsWith('Duda planteada por')) A.push('origen no empieza con "Duda planteada por"');
  else if (!src.autores.some(a => String(o.origen).includes(a))) P.push('origen no coincide con ningun autor del lote');
}

const CHECK = { linkedin: checkLinkedIn, newsletter: checkNewsletter, faq: checkFaq };

function leer(res) {
  if (!res || res.error) {
    const e = res && res.error;
    return { error: 'Error de API: ' + ((e && (e.message || JSON.stringify(e))) || 'respuesta vacia') };
  }
  const cand = res.candidates && res.candidates[0];
  if (!cand || !cand.content || !cand.content.parts)
    return { error: 'Sin contenido (finishReason: ' + (cand && cand.finishReason) + ')' };
  let texto = cand.content.parts.filter(p => p.text && !p.thought).map(p => p.text).join('').trim();
  let envuelto = false;
  if (texto.startsWith('```')) { envuelto = true; texto = texto.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim(); }
  try { return { obj: JSON.parse(texto), texto, envuelto }; }
  catch (e) { return { error: 'JSON invalido: ' + e.message, texto }; }
}

const entradas = $input.all();
const fuente = $('Preparar solicitudes').all();
const filas = [];
entradas.forEach((it, i) => {
  const idx = (it.pairedItem && it.pairedItem.item !== undefined) ? it.pairedItem.item : i;
  const src = fuente[idx].json;
  const exp = (EXPECT[src.activo] || {})[src.caso_id] || {};
  const P = [], A = [];
  const r = leer(it.json);
  let salida = r.texto || '';
  if (r.error) P.push(r.error);
  else {
    if (r.envuelto) P.push('La salida vino dentro de un bloque de codigo; el JSON no se puede guardar directo');
    salida = JSON.stringify(r.obj, null, 2);
    CHECK[src.activo](r.obj, src, exp, P, A);
  }
  const estado = r.error ? 'ERROR' : P.length ? 'FALLA' : A.length ? 'OK con avisos' : 'OK';
  filas.push({ activo: src.activo, caso: src.caso_id, estado, problemas: P.join(' | '), avisos: A.join(' | '), salida });
});
const cuenta = e => filas.filter(f => f.estado === e).length;
const resumen = {
  activo: 'RESUMEN', caso: '',
  estado: `${cuenta('OK')} OK · ${cuenta('OK con avisos')} con avisos · ${cuenta('FALLA')} con fallas · ${cuenta('ERROR')} con error de API (de ${filas.length})`,
  problemas: '', avisos: '', salida: ''
};
return [resumen, ...filas].map(f => ({ json: f }));
